<?php require __DIR__.'/../includes/bootstrap.php';require_role('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$pdo->prepare("UPDATE services SET price=?,visit_charge=?,active=? WHERE id=?")->execute([max(0,floatval($_POST['price'])),max(0,floatval($_POST['visit'])),isset($_POST['active'])?1:0,intval($_POST['id'])]);flash('Service pricing updated.');redirect('services.php');}$services=$pdo->query("SELECT s.*,c.name category FROM services s JOIN service_categories c ON c.id=s.category_id ORDER BY c.id,s.name")->fetchAll();$pageTitle='Services';require __DIR__.'/../includes/header.php';?><div class="dashboard"><aside class="side-nav"><a href="index.php">Overview</a><a href="workers.php">Workers</a><a href="bookings.php">Bookings</a><a class="active" href="services.php">Services & pricing</a></aside><main class="dashboard-main"><h2>Service and pricing management</h2><table><thead><tr><th>Category</th><th>Service</th><th>Service price</th><th>Visit charge</th><th>Active</th><th></th></tr></thead><tbody><?php foreach($services as $s):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($s['id'])?>"><td><?=e($s['category'])?></td><td><?=e($s['name'])?></td><td><input type="number" step=".01" name="price" value="<?=e($s['price'])?>"></td><td><input type="number" step=".01" name="visit" value="<?=e($s['visit_charge'])?>"></td><td><input type="checkbox" name="active" <?=$s['active']?'checked':''?>></td><td><button class="btn btn-primary">Save</button></td></form></tr><?php endforeach?></tbody></table></main></div><?php require __DIR__.'/../includes/footer.php';?>